97	def make_launcher(constants, signature):
98	    def _flatten_signature(sig, output):
99	        # Flatten tuples
100	        if isinstance(sig, tuple):
101	            for x in sig:
102	                _flatten_signature(x, output)
103	        else:
104	            output.append(sig)
105	
106	    def _extracted_type(ty):
107	        if isinstance(ty, tuple):
108	            val = ",".join(map(_extracted_type, ty))
109	            return f"[{val}]"
110	        if ty[0] == "*":
111	            return "PyObject*"
112	        if ty in ("constexpr", "nvTmaDesc"):
113	            return "PyObject*"
114	        return ty_to_cpp(ty)
115	
116	    def format_of(ty):
117	        if isinstance(ty, tuple):
118	            val = "".join(map(format_of, ty))
119	            return f"({val})"
120	        if ty[0] == "*":
121	            return "O"
122	        if ty in ("constexpr", "nvTmaDesc"):
123	            return "O"
124	        return {
125	            "double": "d",
126	            "long": "l",
127	            "int8_t": "b",
128	            "int16_t": "h",
129	            "int32_t": "i",
130	            "int64_t": "L",
131	            "uint8_t": "B",
132	            "uint16_t": "H",
133	            "uint32_t": "I",
134	            "uint64_t": "K",
135	        }[ty_to_cpp(ty)]
136	
137	    args_format = "".join([format_of(ty) for ty in signature.values()])
138	    format = _BASE_ARGS_FORMAT + args_format
139	
140	    flat_signature = []
141	    for sig in signature.values():
142	        _flatten_signature(sig, flat_signature)
143	    signature = {i: s for i, s in enumerate(flat_signature)}
144	    args_list = (
145	        ", " + ", ".join(f"&_arg{i}" for i, ty in signature.items())
146	        if len(signature) > 0
147	        else ""
148	    )
149	    # Record the end of regular arguments;
150	    # subsequent arguments are architecture-specific descriptors, such as tensor descriptors for CUDA.
151	    arg_decl_list = []
152	    for i, ty in signature.items():
153	        if ty == "constexpr":
154	            continue
155	        if ty in FLOAT_STORAGE_TYPE:
156	            arg_decl_list.append(f"{FLOAT_STORAGE_TYPE[ty]} arg{i}")
157	        else:
158	            arg_decl_list.append(f"{ty_to_cpp(ty)} arg{i}")
159	    arg_decls = ", ".join(arg_decl_list)
160	    internal_args_list = []
161	    for i, ty in signature.items():
162	        if ty[0] == "*":
163	            internal_args_list.append(f"ptr_info{i}.dev_ptr")
164	        elif ty in FLOAT_STORAGE_TYPE:
165	            internal_args_list.append(f"_arg{i}_storage")
166	        elif ty == "nvTmaDesc":
167	            # Note: we have to dereference the pointer
168	            internal_args_list.append(f"*tma_ptr{i}")
169	        elif ty != "constexpr":
170	            internal_args_list.append(f"_arg{i}")
