210	static cuLaunchKernelEx_t getLaunchKernelExHandle() {{
211	  // Open the shared library
212	  void* handle = dlopen("libcuda.so.1", RTLD_LAZY);
213	  if (!handle) {{
214	    PyErr_SetString(PyExc_RuntimeError, "Failed to open libcuda.so.1");
