222	  if (dlsym_error) {{
223	    PyErr_SetString(PyExc_RuntimeError, "Failed to retrieve cuLaunchKernelEx from libcuda.so.1");
224	    return NULL;
225	  }}
226	  return cuLaunchKernelExHandle;
