259	typedef struct _DevicePtrInfo {{
260	    CUdeviceptr dev_ptr;
261	    bool valid;
262	}} DevicePtrInfo;
263	
264	static inline DevicePtrInfo getPointer(PyObject *obj, int idx) {{
265	  DevicePtrInfo ptr_info;
266	  ptr_info.dev_ptr = 0;
267	  ptr_info.valid = true;
268	  if (PyLong_Check(obj)) {{
269	    ptr_info.dev_ptr = PyLong_AsUnsignedLongLong(obj);
270	    return ptr_info;
271	  }}
272	  if (obj == Py_None) {{
273	    // valid nullptr
274	    return ptr_info;
275	  }}
276	  PyObject *ptr = PyObject_GetAttrString(obj, "data_ptr");
277	  if(ptr){{
278	    PyObject *empty_tuple = PyTuple_New(0);
279	    PyObject *ret = PyObject_Call(ptr, empty_tuple, NULL);
280	    Py_DECREF(empty_tuple);
281	    Py_DECREF(ptr);
282	    if (!PyLong_Check(ret)) {{
283	      PyErr_SetString(PyExc_TypeError, "data_ptr method of Pointer object must return 64-bit int");
284	      ptr_info.valid = false;
285	      return ptr_info;
286	    }}
287	    ptr_info.dev_ptr = PyLong_AsUnsignedLongLong(ret);
288	    if(!ptr_info.dev_ptr)
289	      return ptr_info;
290	    uint64_t dev_ptr;
291	    int status = cuPointerGetAttribute(&dev_ptr, CU_POINTER_ATTRIBUTE_DEVICE_POINTER, ptr_info.dev_ptr);
292	    if (status == CUDA_ERROR_INVALID_VALUE) {{
293	        PyErr_Format(PyExc_ValueError,
294	                     "Pointer argument (at %d) cannot be accessed from Triton (cpu tensor?)", idx);
295	        ptr_info.valid = false;
296	    }}
297	    ptr_info.dev_ptr = dev_ptr;
298	    Py_DECREF(ret);  // Thanks ChatGPT!
299	    return ptr_info;
300	  }}
301	  PyErr_SetString(PyExc_TypeError, "Pointer argument must be either uint64 or have data_ptr method");
302	  ptr_info.valid = false;
303	  return ptr_info;
304	}}
