306	static uint16_t pack_fp16(double f) {{
307	    uint16_t result;
308	    // from https://github.com/python/pythoncapi-compat
309	#if 0x030600B1 <= PY_VERSION_HEX && PY_VERSION_HEX <= 0x030B00A1 && !defined(PYPY_VERSION)
310	    _PyFloat_Pack2(f, (void*)&result, 1);
311	#else
312	    PyFloat_Pack2(f, (void*)&result, 1);
313	#endif
314	    return result;
315	}}
